const http = require("http");

const port = process.env.PORT || 3000;

const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Hello World</title>
</head>
<body>
  <h1>Hello World</h1>
</body>
</html>
`;

const server = http.createServer((req, res) => {
  if (req.url === "/" || req.url.startsWith("/?")) {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    res.end(html);
  } else {
    res.writeHead(404, { "Content-Type": "text/plain" });
    res.end("Not found");
  }
});

server.listen(port, () => console.log(`Listening on http://localhost:${port}`));
EOF
cat > package.json <<'EOF'
{
  "name": "hello-world",
  "version": "1.0.0",
  "private": true,
  "scripts": { "start": "node server.js" }
}
EOF
cat > README.md <<'EOF'
# Hello World

Minimal Node.js web app using only the built-in `http` module (no dependencies).

## Requirements
Node.js 18+

## Install
No packages to install.

## Run
    npm start

Then open http://localhost:3000. Set `PORT` to use another port (e.g. `PORT=8080 npm start`).
EOF
(PORT=3111 npm start >/dev/null 2>&1 & echo $! >pid); sleep 2; curl -si localhost:3111/ | head -12; pkill -P $(cat pid) ; kill $(cat pid) 2>/dev/null; rm pid

